/* Acceptance for the `with` environment + instance_destroy slice of the C host
 * (c-recon/src/host.c GM_PUSHENV / GM_POPENV_NEXT / instance_destroy).
 *
 * The bodies are shipped bytecode generated by scripts/ir_to_c.py and checked
 * in under c-recon/gen, so the assertions are about the original control flow:
 *   - CODE 164 `gml_Object_obj_boss2_Destroy_0`
 *       instance_activate_all();
 *       if (object_exists(obj_slime))      with (obj_slime)      instance_destroy();
 *       if (object_exists(obj_fireslime))  with (obj_fireslime)  instance_destroy();
 *       instance_create(1024, 256, obj_lloyd);
 *       audio_stop_all(); audio_play_sound(mus_technoending, 0, false);
 *       instance_create(x, y, obj_bosspuff);          <- reads the caller's x/y
 *   - CODE 172 `gml_Object_obj_boss3_Destroy_0`: the same two-step fan-out with
 *     `instance_exists` gates and no `instance_activate_all`, so deactivated
 *     targets stay out of the `with` while still being reachable by id;
 *   - CODE 245/257 (obj_slime / obj_fireslime Destroy_0) bump the kill counters
 *     and spawn one obj_smallpuff at their own x/y - that is how "the Destroy
 *     event ran, exactly once per instance" becomes observable;
 *   - CODE 670/782 (obj_lloyd / obj_smallpuff Create_0) run through
 *     instance_create inside those events.
 *
 * Build (from the repo root):
 *   clang -std=c11 -O2 -Wall -Ic-recon/include \
 *     c-recon/src/host.c c-recon/src/collision.c c-recon/src/objects.c \
 *     c-recon/src/builtins2.c c-recon/gen/objects_data.c c-recon/gen/registry.c \
 *     c-recon/gen/gml_*.c c-recon/gen/sprites.c \
 *     c-recon/tests/env_test.c -o c-recon/build/env_test -lm
 */
#include "gml.h"

#include <stdio.h>
#include <string.h>

/* objects.c, outside the shared host ABI. */
void gm_objects_reset(void);
/* Set when a dispatched body is absent from this binary (objects.c): a fixture
 * that silently lost a Destroy body would otherwise still "pass". */
extern int gm_missing_body_code;

/* c-recon/gen/objects_data.c */
int32_t gm_object_sprite(int32_t id);
int gm_object_create_code(int32_t id);
int gm_object_parent_count(int32_t id);
int32_t gm_object_parent(int32_t id, int index);
int gm_object_exists(int32_t id);

/* Object ids used below (full_ir.json, pinned by objects_test.c). */
#define OBJ_PLAYER 0
#define OBJ_GHOST 24
#define OBJ_BOSS2 26
#define OBJ_BOSS3 27
#define OBJ_SLIME 32
#define OBJ_FIRESLIME 33
#define OBJ_BOSS3PROJECTILE 55
#define OBJ_LLOYD 154
#define OBJ_SMALLPUFF 187
#define OBJ_BOSSPUFF 190

/* CODE ids of the bodies this suite drives. */
#define CODE_BOSS2_DESTROY 164
#define CODE_BOSS3_DESTROY 172

static int checks;
static int failures;

#define CHECK(cond)                                                              \
    do {                                                                         \
        checks++;                                                                \
        if (!(cond)) {                                                           \
            failures++;                                                          \
            fprintf(stderr, "FAIL %s:%d  %s\n", __FILE__, __LINE__, #cond);      \
        }                                                                        \
    } while (0)

#define CHECK_EQ_D(actual, want)                                                 \
    do {                                                                         \
        double a_ = (double)(actual), w_ = (double)(want);                       \
        checks++;                                                                \
        if (!(a_ == w_)) {                                                       \
            failures++;                                                          \
            fprintf(stderr, "FAIL %s:%d  %s == %.17g, want %.17g\n", __FILE__,   \
                    __LINE__, #actual, a_, w_);                                  \
        }                                                                        \
    } while (0)

static GmVM* fresh_vm(int32_t self) {
    static GmVM backing[2];
    static int used;
    GmVM* vm = &backing[used++ % 2];
    vm_init(vm, self);
    gm_objects_reset(); /* stands in for "a new Scene" */
    gm_objects_register_parents();
    return vm;
}

/* A world instance, placed the way a room would place it. */
static int32_t place(GmVM* vm, int32_t id, int32_t object, double x, double y) {
    GmInst* in = vm_add(vm, id, object);
    if (!in) return -1;
    vm_set_field(vm, id, "x", VAL(x));
    vm_set_field(vm, id, "y", VAL(y));
    vm_set_field(vm, id, "sprite_index", VAL(gm_object_sprite(object)));
    return id;
}

static double global_of(GmVM* vm, const char* name) { return GM_READ(vm, -5, name); }

static int count_object(GmVM* vm, int32_t object, int alive_only) {
    int n = 0;
    for (int i = 0; i < vm->ninst; i++) {
        const GmInst* in = &vm->inst[i];
        if (in->object != object) continue;
        if (alive_only && !in->alive) continue;
        n++;
    }
    return n;
}

/* The k-th instance of `object` in table order (fixtures place them in id
 * order, so this is the room's spawn order). */
static GmInst* nth_object(GmVM* vm, int32_t object, int k, int alive_only) {
    for (int i = 0; i < vm->ninst; i++) {
        GmInst* in = &vm->inst[i];
        if (in->object != object) continue;
        if (alive_only && !in->alive) continue;
        if (k-- == 0) return in;
    }
    return NULL;
}

/* Fire a Destroy event the way the engine does: retire the instance, then run
 * its Destroy body. `instance_destroy()` is the shipped path, so use it rather
 * than reaching into the dispatch layer - that also covers the "already dead"
 * guard. */
static void destroy_with_event(GmVM* vm, int32_t id) {
    gm_missing_body_code = -1;
    vm->cur = id;
    (void)GM_CALL(vm, "instance_destroy", 0);
    /* A Destroy (or Create reached from it) that this binary cannot run must not
     * look like a clean event: that is how a fixture loses coverage silently. */
    CHECK_EQ_D(gm_missing_body_code, -1);
}

/* --------------------------------------------------------------- scenarios */

/* Every target of both `with` blocks runs instance_destroy exactly once, and
 * the caller's own Destroy body finishes against its own id afterwards. */
static void test_fan_out_destroys_every_target_once(void) {
    GmVM* vm = fresh_vm(0);
    int32_t player = place(vm, 100000, OBJ_PLAYER, 500, 200);
    int32_t s1 = place(vm, 100001, OBJ_SLIME, 100, 200);
    int32_t s2 = place(vm, 100002, OBJ_SLIME, 120, 200);
    int32_t s3 = place(vm, 100003, OBJ_SLIME, 140, 200);
    int32_t f1 = place(vm, 100004, OBJ_FIRESLIME, 160, 200);
    int32_t f2 = place(vm, 100005, OBJ_FIRESLIME, 180, 200);
    int32_t boss = place(vm, 100006, OBJ_BOSS2, 300, 200);
    CHECK(player >= 0 && s1 >= 0 && boss >= 0);

    destroy_with_event(vm, boss);

    CHECK_EQ_D(vm_inst(vm, boss)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, s1)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, s2)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, s3)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, f1)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, f2)->alive, 0);
    /* The with never reached the player: obj_slime/obj_fireslime are siblings
     * under par_enemy, not parents of obj_player. */
    CHECK_EQ_D(vm_inst(vm, player)->alive, 1);

    /* Each swept instance ran its own Destroy exactly once. */
    CHECK_EQ_D(global_of(vm, "greenslimeskilled"), 3);
    CHECK_EQ_D(global_of(vm, "fireslimeskilled"), 2);
    CHECK_EQ_D(global_of(vm, "enemieskilled"), 5);
    CHECK_EQ_D(count_object(vm, OBJ_SMALLPUFF, 1), 5);

    /* ...one puff per target, at that target's own coordinates. */
    const double want_x[5] = {100, 120, 140, 160, 180};
    for (int k = 0; k < 5; k++) {
        GmInst* puff = nth_object(vm, OBJ_SMALLPUFF, k, 1);
        CHECK(puff != NULL);
        if (puff) {
            CHECK_EQ_D(gm_field_or(puff, "x", -1), want_x[k]);
            CHECK_EQ_D(gm_field_or(puff, "y", -1), 200);
        }
    }

    /* The tail of CODE 164 runs on the boss, not on the last sweep target:
     * Lloyd on its fixed spawn, and the puff on the boss's own x/y. That is the
     * environment restore being observable through shipped behaviour. */
    CHECK_EQ_D(count_object(vm, OBJ_LLOYD, 1), 1);
    GmInst* lloyd = nth_object(vm, OBJ_LLOYD, 0, 1);
    CHECK(lloyd != NULL);
    if (lloyd) {
        CHECK_EQ_D(gm_field_or(lloyd, "x", -1), 1024);
        CHECK_EQ_D(gm_field_or(lloyd, "y", -1), 256);
    }
    CHECK_EQ_D(count_object(vm, OBJ_BOSSPUFF, 1), 1);
    GmInst* puff = nth_object(vm, OBJ_BOSSPUFF, 0, 1);
    CHECK(puff != NULL);
    if (puff) {
        CHECK_EQ_D(gm_field_or(puff, "x", -1), 300);
        CHECK_EQ_D(gm_field_or(puff, "y", -1), 200);
    }

    /* Every environment frame was popped and `self` was handed back. */
    CHECK_EQ_D(vm->nenv, 0);
    CHECK_EQ_D(vm->cur, boss);
    CHECK_EQ_D(gm_missing_body_code, -1);
}

/* An empty receiver set still walks the generated control flow: pushenv jumps AT
 * the popenv, so the body is skipped and the frame never leaks. */
static void test_empty_selection_still_pops_the_environment(void) {
    GmVM* vm = fresh_vm(0);
    place(vm, 100000, OBJ_PLAYER, 500, 200);
    int32_t boss = place(vm, 100001, OBJ_BOSS2, 300, 240);

    destroy_with_event(vm, boss);

    CHECK_EQ_D(vm_inst(vm, boss)->alive, 0);
    CHECK_EQ_D(global_of(vm, "greenslimeskilled"), 0);
    CHECK_EQ_D(global_of(vm, "fireslimeskilled"), 0);
    CHECK_EQ_D(global_of(vm, "enemieskilled"), 0);
    CHECK_EQ_D(count_object(vm, OBJ_SMALLPUFF, 0), 0);
    CHECK_EQ_D(count_object(vm, OBJ_LLOYD, 1), 1);
    CHECK_EQ_D(count_object(vm, OBJ_BOSSPUFF, 1), 1);
    GmInst* puff = nth_object(vm, OBJ_BOSSPUFF, 0, 1);
    if (puff) {
        CHECK_EQ_D(gm_field_or(puff, "x", -1), 300);
        CHECK_EQ_D(gm_field_or(puff, "y", -1), 240);
    }
    CHECK_EQ_D(vm->nenv, 0);
    CHECK_EQ_D(vm->cur, boss);
}

/* Empty selection at depth > 0 must push and pop an empty frame. Otherwise the
 * popenv belonging to the inner body advances the OUTER with and can destroy
 * the next boss during CODE 164's own empty slime sweep. */
static void test_nested_empty_selection_preserves_outer_frame(void) {
    GmVM* vm = fresh_vm(0);
    int32_t player = place(vm, 100000, OBJ_PLAYER, 500, 200);
    int32_t boss_a = place(vm, 100001, OBJ_BOSS2, 300, 200);
    int32_t boss_b = place(vm, 100002, OBJ_BOSS2, 500, 200);

    vm->cur = player;
    CHECK_EQ_D(GM_PUSHENV(vm, VAL(OBJ_BOSS2)), 1);
    CHECK_EQ_D(vm->cur, boss_a);
    CHECK_EQ_D(vm->nenv, 1);

    /* No slimes exist, so both inner selections in shipped CODE 164 are empty.
     * The first one must not advance the outer boss iteration and kill boss_b. */
    destroy_with_event(vm, boss_a);
    CHECK_EQ_D(vm_inst(vm, boss_a)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, boss_b)->alive, 1);
    CHECK_EQ_D(count_object(vm, OBJ_LLOYD, 1), 1);
    CHECK_EQ_D(vm->nenv, 1);
    CHECK_EQ_D(vm->cur, boss_a);

    CHECK_EQ_D(GM_POPENV_NEXT(vm), 1);
    CHECK_EQ_D(vm->cur, boss_b);
    CHECK_EQ_D(vm->nenv, 1);
    CHECK_EQ_D(GM_POPENV_NEXT(vm), 0);
    CHECK_EQ_D(vm->cur, player);
    CHECK_EQ_D(vm->nenv, 0);
}

/* A retired instance is not in the `with` set: its Destroy must not run a second
 * time, which the counters show (2 live slimes => 2, not 3). */
static void test_retired_target_is_not_swept_again(void) {
    GmVM* vm = fresh_vm(0);
    place(vm, 100000, OBJ_PLAYER, 500, 200);
    int32_t s1 = place(vm, 100001, OBJ_SLIME, 100, 200);
    int32_t s2 = place(vm, 100002, OBJ_SLIME, 120, 200);
    int32_t s3 = place(vm, 100003, OBJ_SLIME, 140, 200);
    int32_t boss = place(vm, 100006, OBJ_BOSS2, 300, 200);

    /* s2 died before the sweep, as a slime killed by the player would be. */
    vm_inst(vm, s2)->alive = 0;

    destroy_with_event(vm, boss);

    CHECK_EQ_D(vm_inst(vm, s1)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, s2)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, s3)->alive, 0);
    CHECK_EQ_D(global_of(vm, "greenslimeskilled"), 2);
    CHECK_EQ_D(global_of(vm, "enemieskilled"), 2);
    CHECK_EQ_D(count_object(vm, OBJ_SMALLPUFF, 1), 2);
    GmInst* first = nth_object(vm, OBJ_SMALLPUFF, 0, 1);
    GmInst* second = nth_object(vm, OBJ_SMALLPUFF, 1, 1);
    if (first) CHECK_EQ_D(gm_field_or(first, "x", -1), 100);
    if (second) CHECK_EQ_D(gm_field_or(second, "x", -1), 140);
}

/* The destroy() alive guard alone cannot prove selection: even an incorrect
 * `with` that admitted a dead target would no-op on it. Inspect the selection
 * itself so the dead instance cannot be exposed as a second iteration. */
static void test_with_selector_itself_excludes_retired_instances(void) {
    GmVM* vm = fresh_vm(0);
    int32_t player = place(vm, 100000, OBJ_PLAYER, 500, 200);
    int32_t live = place(vm, 100001, OBJ_SLIME, 100, 200);
    int32_t dead = place(vm, 100002, OBJ_SLIME, 120, 200);
    vm_inst(vm, dead)->alive = 0;

    vm->cur = player;
    CHECK_EQ_D(GM_PUSHENV(vm, VAL(OBJ_SLIME)), 1);
    CHECK_EQ_D(vm->cur, live);
    CHECK_EQ_D(GM_POPENV_NEXT(vm), 0); /* no second iteration on `dead` */
    CHECK_EQ_D(vm->cur, player);
    CHECK_EQ_D(vm->nenv, 0);
}

/* Destroying an already retired instance is a no-op: the event is not re-entered
 * (the same guard that keeps a Destroy body from destroying itself twice). */
static void test_second_destroy_does_not_rerun_the_event(void) {
    GmVM* vm = fresh_vm(0);
    place(vm, 100000, OBJ_PLAYER, 500, 200);
    place(vm, 100001, OBJ_SLIME, 100, 200);
    place(vm, 100002, OBJ_SLIME, 120, 200);
    int32_t boss = place(vm, 100006, OBJ_BOSS2, 300, 200);

    destroy_with_event(vm, boss);
    int smokes = count_object(vm, OBJ_SMALLPUFF, 1);
    int lloyds = count_object(vm, OBJ_LLOYD, 1);
    int puffs = count_object(vm, OBJ_BOSSPUFF, 1);
    CHECK_EQ_D(smokes, 2);
    CHECK_EQ_D(lloyds, 1);
    CHECK_EQ_D(puffs, 1);

    destroy_with_event(vm, boss); /* boss is already dead */

    CHECK_EQ_D(count_object(vm, OBJ_SMALLPUFF, 1), smokes);
    CHECK_EQ_D(count_object(vm, OBJ_LLOYD, 1), lloyds);
    CHECK_EQ_D(count_object(vm, OBJ_BOSSPUFF, 1), puffs);
    CHECK_EQ_D(global_of(vm, "greenslimeskilled"), 2);
    CHECK_EQ_D(global_of(vm, "enemieskilled"), 2);
    CHECK_EQ_D(vm->nenv, 0);

    /* Running the same body a second time on the boss is a different thing from
     * destroying a dead instance: the body does run, and the sweep is empty
     * because both slimes are retired. Counters must still not move. */
    vm->cur = boss;
    CHECK_EQ_D(gm_dispatch_event(vm, boss, 1, 0), 0);
    CHECK_EQ_D(global_of(vm, "greenslimeskilled"), 2);
    CHECK_EQ_D(count_object(vm, OBJ_SMALLPUFF, 1), smokes);
    CHECK_EQ_D(count_object(vm, OBJ_LLOYD, 1), lloyds + 1);
    CHECK_EQ_D(count_object(vm, OBJ_BOSSPUFF, 1), puffs + 1);
}

/* active vs alive: `with` and instance_exists see only active instances, while
 * variable access still reaches a deactivated one (ir_scene.rs select() vs
 * select_for_access()). CODE 172 has no instance_activate_all, so a deactivated
 * ghost stays parked. */
static void test_with_skips_deactivated_targets(void) {
    GmVM* vm = fresh_vm(0);
    place(vm, 100000, OBJ_PLAYER, 500, 200);
    int32_t ghost_a = place(vm, 100001, OBJ_GHOST, 100, 200);
    int32_t ghost_b = place(vm, 100002, OBJ_GHOST, 120, 200);
    int32_t proj_a = place(vm, 100003, OBJ_BOSS3PROJECTILE, 140, 200);
    int32_t proj_b = place(vm, 100004, OBJ_BOSS3PROJECTILE, 160, 200);
    int32_t boss = place(vm, 100005, OBJ_BOSS3, 300, 220);

    vm_inst(vm, ghost_b)->active = 0;
    vm_inst(vm, proj_b)->active = 0;

    destroy_with_event(vm, boss);

    CHECK_EQ_D(vm_inst(vm, ghost_a)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, ghost_b)->alive, 1);
    CHECK_EQ_D(vm_inst(vm, ghost_b)->active, 0);
    CHECK_EQ_D(vm_inst(vm, proj_a)->alive, 0);
    CHECK_EQ_D(vm_inst(vm, proj_b)->alive, 1);
    CHECK_EQ_D(vm_inst(vm, proj_b)->active, 0);
    /* Only the active ghost ran its own Destroy (CODE 146). */
    CHECK_EQ_D(global_of(vm, "ghostskilled"), 1);
    CHECK_EQ_D(global_of(vm, "enemieskilled"), 1);
    CHECK_EQ_D(count_object(vm, OBJ_SMALLPUFF, 1), 1);
    GmInst* smoke = nth_object(vm, OBJ_SMALLPUFF, 0, 1);
    if (smoke) {
        CHECK_EQ_D(gm_field_or(smoke, "x", -1), 100);
        CHECK_EQ_D(gm_field_or(smoke, "y", -1), 200);
    }
    CHECK_EQ_D(count_object(vm, OBJ_BOSSPUFF, 1), 1);
    GmInst* puff = nth_object(vm, OBJ_BOSSPUFF, 0, 1);
    if (puff) {
        CHECK_EQ_D(gm_field_or(puff, "x", -1), 300);
        CHECK_EQ_D(gm_field_or(puff, "y", -1), 220);
    }
    CHECK_EQ_D(vm->nenv, 0);

    /* A read by id still resolves a deactivated instance... */
    CHECK_EQ_D(GM_READ(vm, VAL(100002), "x"), 120);
    /* ...and an object-selector write falls back to the alive-only set when the
     * strict (alive && active) set is empty - so it lands on the parked ghost. */
    GM_WRITE(vm, VAL(OBJ_GHOST), "marked", VAL(7));
    CHECK_EQ_D(GM_READ(vm, VAL(100002), "marked"), 7);
    CHECK_EQ_D(GM_READ(vm, VAL(100001), "marked"), 0); /* the dead one is untouched */

    /* instance_exists() is the strict set: with every ghost parked it is false,
     * which is the branch CODE 172 uses to skip the sweep entirely. */
    vm_inst(vm, ghost_b)->active = 0;
    CHECK_EQ_D(GM_CALL(vm, "instance_exists", 1, VAL(OBJ_GHOST)), 0);
    vm_inst(vm, ghost_b)->active = 1;
    CHECK_EQ_D(GM_CALL(vm, "instance_exists", 1, VAL(OBJ_GHOST)), 1);
}

/* Nested `with` frames: the inner popenv restores the OUTER target, not the
 * original self, so the remaining outer iterations continue on the right
 * instance (CODE 361 is the only shipped body that nests, and its inner
 * receiver is `id`, i.e. the outer target). */
static void test_nested_environments_restore_the_outer_target(void) {
    GmVM* vm = fresh_vm(0);
    int32_t player = place(vm, 100000, OBJ_PLAYER, 500, 200);
    int32_t s1 = place(vm, 100001, OBJ_SLIME, 100, 200);
    int32_t s2 = place(vm, 100002, OBJ_SLIME, 120, 200);

    vm->cur = player;
    CHECK_EQ_D(GM_PUSHENV(vm, VAL(OBJ_SLIME)), 1);
    CHECK_EQ_D(vm->cur, s1);
    CHECK_EQ_D(vm->nenv, 1);

    /* inner with (id) - the receiver is the outer target's absolute id */
    CHECK_EQ_D(GM_PUSHENV(vm, VAL(s1)), 1);
    CHECK_EQ_D(vm->cur, s1);
    CHECK_EQ_D(vm->nenv, 2);

    /* inner exhausted: cur goes back to the outer target, frame count drops */
    CHECK_EQ_D(GM_POPENV_NEXT(vm), 0);
    CHECK_EQ_D(vm->cur, s1);
    CHECK_EQ_D(vm->nenv, 1);

    /* outer advances to the second slime, not to self */
    CHECK_EQ_D(GM_POPENV_NEXT(vm), 1);
    CHECK_EQ_D(vm->cur, s2);
    CHECK_EQ_D(vm->nenv, 1);

    CHECK_EQ_D(GM_POPENV_NEXT(vm), 0);
    CHECK_EQ_D(vm->cur, player);
    CHECK_EQ_D(vm->nenv, 0);

    /* An empty selection still pushes an empty frame; the matching popenv
     * removes it without changing cur or disturbing any outer frame. */
    CHECK_EQ_D(GM_PUSHENV(vm, VAL(OBJ_FIRESLIME)), 0);
    CHECK_EQ_D(vm->nenv, 1);
    CHECK_EQ_D(vm->cur, player);
    CHECK_EQ_D(GM_POPENV_NEXT(vm), 0);
    CHECK_EQ_D(vm->cur, player);
    CHECK_EQ_D(vm->nenv, 0);
}

/* The two bodies this suite drives are the shipped ones, not lookalikes. */
static void test_bodies_are_the_shipped_ones(void) {
    CHECK_EQ_D(gm_object_exists(OBJ_BOSS2), 1);
    CHECK_EQ_D(gm_object_exists(OBJ_BOSS3), 1);
    GmVM* vm = fresh_vm(0);
    (void)vm;
    CHECK_EQ_D(CODE_BOSS2_DESTROY, 164);
    CHECK_EQ_D(CODE_BOSS3_DESTROY, 172);
}

int main(void) {
    test_bodies_are_the_shipped_ones();
    test_fan_out_destroys_every_target_once();
    test_empty_selection_still_pops_the_environment();
    test_nested_empty_selection_preserves_outer_frame();
    test_retired_target_is_not_swept_again();
    test_with_selector_itself_excludes_retired_instances();
    test_second_destroy_does_not_rerun_the_event();
    test_with_skips_deactivated_targets();
    test_nested_environments_restore_the_outer_target();

    printf("env checks: %d, failures: %d\n", checks, failures);
    return failures == 0 ? 0 : 1;
}
